#!/usr/bin/env node
// Metro can only bundle files named in a static require(), so this writes one require per
// recording listed in content/reciters.json. Runs before start/build; the output is committed.
import { readFileSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const MOBILE = join(dirname(fileURLToPath(import.meta.url)), '..');
const reciters = JSON.parse(readFileSync(join(MOBILE, '..', 'content', 'reciters.json'), 'utf8'));

const lines = [
  '// Generated by scripts/gen-audio-index.mjs — do not edit.',
  '/* eslint-disable */',
  'export const audioIndex: Record<string, Record<string, number>> = {',
];
for (const [rid, r] of Object.entries(reciters)) {
  lines.push(`  '${rid}': {`);
  for (const id of r.recorded) lines.push(`    '${id}': require('../../../content/audio/${rid}/${id}.m4a'),`);
  lines.push('  },');
}
lines.push('};', '');

writeFileSync(join(MOBILE, 'src', 'content', 'audio-index.ts'), lines.join('\n'));
console.log(`audio index: ${Object.values(reciters).reduce((n, r) => n + r.recorded.length, 0)} recordings`);
